CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "password" TEXT NOT NULL, "name" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Site" ("id" TEXT PRIMARY KEY, "domain" TEXT NOT NULL, "siteKey" TEXT NOT NULL UNIQUE, "secretKey" TEXT NOT NULL, "verificationSecretHash" TEXT, "isVerified" BOOLEAN NOT NULL DEFAULT false, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE("userId","domain"));
CREATE TABLE "ValidationLog" ("id" TEXT PRIMARY KEY, "siteId" TEXT NOT NULL REFERENCES "Site"("id") ON DELETE CASCADE, "ip" TEXT NOT NULL, "country" TEXT DEFAULT 'Unknown', "type" TEXT NOT NULL, "riskScore" DOUBLE PRECISION NOT NULL, "reason" TEXT NOT NULL, "latencyMs" INTEGER, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ON "ValidationLog"("siteId","createdAt");
CREATE TABLE organization (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE membership (org TEXT NOT NULL REFERENCES organization(id), account TEXT NOT NULL REFERENCES "User"("id"), role TEXT NOT NULL CHECK(role IN ('owner','member')), PRIMARY KEY(org,account));
CREATE TABLE site_tenant (site TEXT PRIMARY KEY REFERENCES "Site"("id"), org TEXT NOT NULL REFERENCES organization(id));
CREATE TABLE pilot (org TEXT PRIMARY KEY REFERENCES organization(id), starts TIMESTAMPTZ NOT NULL, ends TIMESTAMPTZ NOT NULL, period_start TIMESTAMPTZ NOT NULL, period_end TIMESTAMPTZ NOT NULL, revoked BOOLEAN NOT NULL DEFAULT false, overage BOOLEAN NOT NULL DEFAULT false, cap BIGINT NOT NULL DEFAULT 0 CHECK(cap>=0), consent_at TIMESTAMPTZ, CHECK(starts<ends), CHECK(period_start<period_end));
CREATE TABLE pilot_request (org TEXT PRIMARY KEY REFERENCES organization(id), requested_by TEXT NOT NULL REFERENCES "User"("id"), requested_at TIMESTAMPTZ NOT NULL DEFAULT now(), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','revoked')));
CREATE TABLE usage_period (deployment TEXT NOT NULL, org TEXT NOT NULL REFERENCES organization(id), start_at TIMESTAMPTZ NOT NULL, used BIGINT NOT NULL DEFAULT 0 CHECK(used>=0), PRIMARY KEY(deployment,org,start_at));
CREATE TABLE verification_receipt (deployment TEXT NOT NULL, tenant TEXT NOT NULL, site TEXT NOT NULL, jti TEXT NOT NULL, consumed_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(deployment,tenant,site,jti));
CREATE TABLE audit_event (id BIGSERIAL PRIMARY KEY, actor TEXT NOT NULL, kind TEXT NOT NULL, subject TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE passkey (id TEXT PRIMARY KEY, account TEXT NOT NULL REFERENCES "User"("id"), public_key BYTEA NOT NULL, counter BIGINT NOT NULL, backed_up BOOLEAN NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE trust_challenge (id TEXT PRIMARY KEY, account TEXT NOT NULL REFERENCES "User"("id"), kind TEXT NOT NULL, challenge TEXT NOT NULL, binding JSONB NOT NULL, expires TIMESTAMPTZ NOT NULL);
CREATE TABLE trust_device (id TEXT PRIMARY KEY, account TEXT NOT NULL REFERENCES "User"("id"), public_key JSONB NOT NULL, revoked BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE trust_grant (id TEXT PRIMARY KEY, account TEXT NOT NULL REFERENCES "User"("id"), device TEXT NOT NULL REFERENCES trust_device(id), deployment TEXT NOT NULL, scope JSONB NOT NULL, expires TIMESTAMPTZ NOT NULL, budget INTEGER NOT NULL CHECK(budget BETWEEN 0 AND 20), revoked BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE trust_nonce (id TEXT PRIMARY KEY, grant_id TEXT NOT NULL REFERENCES trust_grant(id), context JSONB NOT NULL, expires TIMESTAMPTZ NOT NULL);
CREATE TABLE trust_site_usage (grant_id TEXT NOT NULL REFERENCES trust_grant(id), site TEXT NOT NULL, used INTEGER NOT NULL CHECK(used BETWEEN 1 AND 20), PRIMARY KEY(grant_id,site));
